/* Reusable dropdowns: inventory collections and non-inventory record lists. */
function ensureSources(){ensureItemState();state.dataSources??=[];for(const c of state.itemCategories.filter(c=>!c.parentId)){const existing=state.dataSources.find(s=>s.kind==='items'&&s.categoryId===c.id);if(existing){existing.name=c.name;existing.owner=c.module;}else state.dataSources.push({id:'source-'+c.id,name:c.name,owner:c.module,kind:'items',categoryId:c.id,shares:[],revision:1});}if(!state.sourcesSeeded){state.dataSources.push({id:'source-vendors',name:'Approved vendors',owner:'Procurement',kind:'records',shares:['Sales','Feed'],revision:1,records:[{id:'vendor-north',name:'North supplier · demo',active:true},{id:'vendor-local',name:'Local supplier · demo',active:true}]},{id:'source-pens',name:'Pens & locations',owner:'Counts',kind:'records',shares:['Weighing','Feed','Health','Procurement'],revision:1,records:[{id:'pen-cbe-1',name:'CBE · Pen 1',active:true},{id:'pen-cbe-2',name:'CBE · Pen 2',active:true}]});state.sourcesSeeded=true;}return state.dataSources;}
function sourceById(id){return ensureSources().find(s=>s.id===id)}
function sourceMembers(s){return s.kind==='items'?state.items.filter(i=>i.module===s.owner&&i.categoryId===s.categoryId):(s.records||[]).map(i=>({...i,module:s.owner,unit:'record',purpose:s.name,revision:s.revision}));}
function sourceOptions(s,m=current){if(!s)return [];return sourceMembers(s).filter(i=>i.active&&(s.owner===m||s.shares.includes(m)||(s.kind==='items'&&i.shares.includes(m))));}
function visibleSources(m=current){return ensureSources().filter(s=>s.owner===m||s.shares.includes(m)||sourceOptions(s,m).length);}
const sourcesOldAvailable=availableItems;
availableItems=function(m){ensureSources();return state.items.filter(i=>i.active&&(i.module===m||i.shares.includes(m)||state.dataSources.some(s=>s.kind==='items'&&s.owner===i.module&&s.categoryId===i.categoryId&&s.shares.includes(m))));};
const sourcesOldCatalogue=nodeCatalogue;
nodeCatalogue=function(n,m=current){return n.catalogueSourceId?sourceOptions(sourceById(n.catalogueSourceId),m):sourcesOldCatalogue(n,m);};
function sourceDependencies(id,m){return allWorkflowDrafts().filter(([mod,s])=>(!m||mod===m)&&s.nodes.some(n=>n.catalogueSourceId===id||n.resourceSourceId===id));}
function toggleSourceAccess(id,m,on){if(!canEdit())return;const s=sourceById(id);if(!s||m===s.owner)return;if(!on){modal('Review source access',`<p>Remove whole-source access to ${esc(s.name)} for ${esc(m)}?</p><p>${sourceDependencies(id,m).length} workflow drafts reference this source. Published snapshots stay unchanged. Items shared individually remain available.</p><button class="danger" onclick="applySourceAccess('${id}','${m}',false);closeModal();render()">Remove source access</button><button onclick="closeModal();render()">Keep access</button>`);return;}applySourceAccess(id,m,true);}
function applySourceAccess(id,m,on){if(!canEdit())return;const s=sourceById(id);if(!s||s.owner===m)return;s.shares=s.shares.filter(x=>x!==m);if(on)s.shares.push(m);s.revision++;record('Updated source access: '+s.name+' / '+m);render();}
let sourceDirectoryOwner='',sourceDirectoryKind='';const sourcePickerFilters={};
function showSources(){const list=ensureSources().filter(s=>(!sourceDirectoryOwner||s.owner===sourceDirectoryOwner)&&(!sourceDirectoryKind||s.kind===sourceDirectoryKind));$('#content').innerHTML=`<div class="heading"><div><h2>Reusable dropdown sources</h2><p>Choose a source in any SOP question or action. Its owner maintains the records.</p></div><button class="primary" onclick="sourceModal()" ${canEdit()?'':'disabled'}>+ New record source</button></div><div class="notice">Whole-source sharing includes current and future active records. Existing individual item shares are additional access. Published SOPs retain the selected source snapshot.</div><div class="inputrow source-directory-filters"><label class="field"><span>Owner</span><select aria-label="Source directory owner" onchange="sourceDirectoryOwner=this.value;showSources()"><option value="">All modules</option>${modules.map(m=>`<option ${sourceDirectoryOwner===m?'selected':''}>${m}</option>`).join('')}</select></label><label class="field"><span>Source type</span><select aria-label="Source directory type" onchange="sourceDirectoryKind=this.value;showSources()"><option value="">All types</option><option value="items" ${sourceDirectoryKind==='items'?'selected':''}>Item collections</option><option value="records" ${sourceDirectoryKind==='records'?'selected':''}>Record lists</option></select></label></div><div class="sources-grid">${list.map(s=>`<section class="card"><div class="cardheader"><div><span class="eyebrow">${esc(s.owner)} · ${s.kind==='items'?'ITEM COLLECTION':'RECORD LIST'}</span><h2>${esc(s.name)}</h2></div><span class="badge blue">${sourceMembers(s).filter(i=>i.active).length} active</span></div><p>${s.kind==='items'?'Maintained in Items Config; grouped by category.':'Local example list. No connection to production records.'}</p><label class="field"><span>Preview as module</span><select aria-label="Preview ${esc(s.name)} as module" onchange="previewSource('${s.id}',this.value)">${modules.map(m=>`<option ${m==='Health'?'selected':''}>${m}</option>`).join('')}</select></label><div id="preview-${s.id}" class="source-preview">${sourcePreview(s,'Health')}</div><details><summary>Share entire source</summary><div class="item-share-grid">${modules.map(m=>`<label class="checkrow"><input type="checkbox" aria-label="Share source ${esc(s.name)} with ${m}" ${s.owner===m||s.shares.includes(m)?'checked':''} ${!canEdit()||s.owner===m?'disabled':''} onchange="toggleSourceAccess('${s.id}','${m}',this.checked)">${m}</label>`).join('')}</div></details><div class="actions"><button onclick="sourceModal('${s.id}')">${s.kind==='items'?'View collection':'Manage records'} →</button><button onclick="go('${s.owner}','SOPs')">Owner SOPs →</button></div></section>`).join('')}</div>`;}
function sourcePreview(s,m){const opts=sourceOptions(s,m);return `<span class="muted">${opts.length} choices visible to ${esc(m)}</span><select aria-label="${esc(s.name)} preview choices"><option>${opts.length?'Choose a record…':'No access or active records'}</option>${opts.map(i=>`<option>${esc(i.name)}</option>`).join('')}</select>`;}
function previewSource(id,m){const s=sourceById(id);$('#preview-'+id).innerHTML=sourcePreview(s,m);}
function sourceModal(id){const s=id?sourceById(id):null;if(s?.kind==='items'){modal(s.name,`<span class="eyebrow">${esc(s.owner)} · ${esc(itemCategoryName(s.categoryId))}</span><p>New active items in this category automatically join the source. Item-level shares and whole-source shares both grant visibility.</p>${sourceMembers(s).map(i=>`<div class="linkline"><span>${esc(i.name)}</span><span class="badge">${i.active?'Active':'Archived'}</span></div>`).join('')}<button onclick="closeModal();go('Items');itemFilter.module='${s.owner}';itemFilter.category='${s.categoryId}';renderItems()">Manage collection in Items Config →</button>`);return;}const dis=canEdit()?'':'disabled';modal(s?'Manage record source':'New record source',`<label class="field"><span>Source name</span><input id="source-name" value="${esc(s?.name||'')}" ${dis}></label><label class="field"><span>Owning module</span><select id="source-owner" ${s?'disabled':dis}>${modules.map(m=>`<option ${m===(s?.owner||'Procurement')?'selected':''}>${m}</option>`).join('')}</select></label><div class="notice">${s?sourceDependencies(s.id).length+' workflow draft(s) use this source. Archiving records can block new publication. ':''}Each line is one dropdown choice. Existing record IDs are retained by editing records below.</div>${s?`<div>${s.records.map(r=>`<div class="source-record"><input aria-label="Record ${esc(r.name)}" data-record-id="${r.id}" value="${esc(r.name)}" ${dis}><label class="checkrow"><input type="checkbox" data-record-active="${r.id}" ${r.active?'checked':''} ${dis}>Active</label></div>`).join('')}</div>`:''}<label class="field"><span>${s?'Add records (one per line)':'Records (one per line)'}</span><textarea id="source-new-records" ${dis}></textarea></label><button class="primary" onclick="saveSource('${id||''}')" ${dis}>Save source</button>`);}
function saveSource(id){if(!canEdit())return;const old=sourceById(id),name=$('#source-name').value.trim(),owner=old?.owner||$('#source-owner').value;if(!name)return toast('Enter a source name.');if(ensureSources().some(s=>s.id!==id&&s.owner===owner&&s.name.toLowerCase()===name.toLowerCase()))return toast('This owner already has a source with that name.');const records=old?old.records.map(r=>({...r,name:document.querySelector('[data-record-id="'+r.id+'"]').value.trim(),active:document.querySelector('[data-record-active="'+r.id+'"]').checked})):[];for(const n of $('#source-new-records').value.split('\n').map(x=>x.trim()).filter(Boolean))records.push({id:'record-'+crypto.randomUUID(),name:n,active:true});if(!records.length||records.some(r=>!r.name)||new Set(records.map(r=>r.name.toLowerCase())).size!==records.length)return toast('Add unique, non-empty record names.');const next={id:id||'source-'+crypto.randomUUID(),name,owner,kind:'records',shares:old?.shares||[],revision:(old?.revision||0)+1,records};if(old&&old.records.some(r=>r.active&&!next.records.find(n=>n.id===r.id)?.active)){window.pendingSource=next;modal('Review archived records',`<p>${sourceDependencies(id).length} workflow drafts reference this source. Archived choices disappear from new selections; affected decisions and actions must be fixed before publishing. Published snapshots stay unchanged.</p><button class="danger" onclick="commitSource(window.pendingSource)">Save and archive records</button><button onclick="sourceModal('${id}')">Discard changes and return</button>`);return;}commitSource(next);}
const sourceOldRender=render;
render=function(){sourceOldRender();if(current==='Common'&&tab!=='Editor'){const t=$('.tabs');if(t)t.insertAdjacentHTML('afterbegin',`<button class="${tab==='Data sources'?'active':''}" onclick="go('Common','Data sources')">Data sources</button>`);if(tab==='Data sources')showSources();}};
function sourceSelect(value,attr,kind){const f=sourcePickerFilters[attr]||{},all=visibleSources(current),list=all.filter(s=>(!kind||s.kind===kind)&&(!f.owner||s.owner===f.owner)&&(!f.kind||s.kind===f.kind));const chosen=all.find(s=>s.id===value);if(chosen&&!list.includes(chosen))list.unshift(chosen);return `<div class="source-picker-filters"><select aria-label="Source owner filter" onchange="filterSourcePicker('${attr}','owner',this.value)"><option value="">All owners</option>${modules.map(m=>`<option ${f.owner===m?'selected':''}>${m}</option>`).join('')}</select><select aria-label="Source type filter" onchange="filterSourcePicker('${attr}','kind',this.value)"><option value="">All types</option><option value="items" ${f.kind==='items'?'selected':''}>Item collections</option><option value="records" ${f.kind==='records'?'selected':''}>Record lists</option></select></div><select aria-label="${attr==='catalogueSourceId'?'Dropdown source':'Action source'}" onchange="setNodeSource('${attr}',this.value)"><option value="">Choose a shared source…</option>${value&&!all.some(s=>s.id===value)?`<option selected disabled value="${esc(value)}">Source access removed</option>`:''}${list.map(s=>`<option value="${s.id}" ${value===s.id?'selected':''}>${esc(s.owner)} · ${esc(s.name)}</option>`).join('')}</select>`;}
function filterSourcePicker(attr,key,value){sourcePickerFilters[attr]??={};sourcePickerFilters[attr][key]=value;inspect();}
function setNodeSource(attr,id){if(!canEdit())return;const n=sop().nodes.find(n=>n.id===selected);n[attr]=id;if(attr==='resourceSourceId')n.resourceId='';persist();drawGraph();inspect();}
const sourceOldInspect=inspect;
inspect=function(){sourceOldInspect();const n=sop().nodes.find(n=>n.id===selected),p=$('#inspector');if(!n||!p||!canEdit())return;if(n.type==='question'&&n.answer==='Catalogue'){p.querySelector('.catalogue-config')?.remove();p.insertAdjacentHTML('beforeend',`<div class="catalogue-config"><label class="field"><span>Dropdown source</span>${sourceSelect(n.catalogueSourceId,'catalogueSourceId')}</label><p class="muted">${n.catalogueSourceId?nodeCatalogue(n).length+' choices available':'Legacy module catalogue until a named source is selected'}. Ownership and sharing determine what appears.</p><button onclick="go('Common','Data sources')">Manage sources →</button></div>`);}if(n.type==='action'){const a=p.querySelector('[aria-label="Action type"]');if(a&&!Array.from(a.options).some(o=>o.value==='Use shared resource'))a.insertAdjacentHTML('beforeend','<option>Use shared resource</option>');if(n.action==='Use shared resource'){a.value=n.action;const src=sourceById(n.resourceSourceId),opts=sourceOptions(src,current);p.insertAdjacentHTML('beforeend',`<label class="field"><span>Shared resource source</span>${sourceSelect(n.resourceSourceId,'resourceSourceId')}</label><label class="field"><span>Record / item</span><select aria-label="Shared resource" onchange="editNode('resourceId',this.value,true)"><option value="">Choose record…</option>${n.resourceId&&!opts.some(i=>i.id===n.resourceId)?'<option selected disabled>Unavailable selection</option>':''}${opts.map(i=>`<option value="${i.id}" ${n.resourceId===i.id?'selected':''}>${esc(i.name)}</option>`).join('')}</select></label><p class="hint">Reference only. This action does not purchase, administer, allocate stock or grant access.</p>`);}}};
const sourceOldValidate=validateWorkflow;
validateWorkflow=function(s,m=current){const normalized=structuredClone(s);for(const n of normalized.nodes)if(n.action==='Use shared resource')n.action='Instruction';const errors=sourceOldValidate(normalized,m);for(const n of s.nodes){if(n.answer==='Catalogue'&&n.catalogueSourceId&&!sourceById(n.catalogueSourceId))errors.push(n.label+': source no longer exists.');if(n.action==='Use shared resource'&&!sourceOptions(sourceById(n.resourceSourceId),m).some(i=>i.id===n.resourceId))errors.push(n.label+': choose an available shared resource.');}return [...new Set(errors)];};
const sourceOldCompile=compileWorkflow;
compileWorkflow=function(s,m=current,version=s.version||0){const d=sourceOldCompile(s,m,version);d.sources={};for(const n of d.nodes){const id=n.catalogueSourceId||n.resourceSourceId;if(id){const src=sourceById(id);d.sources[id]={id:src.id,name:src.name,owner:src.owner,revision:src.revision};}if(n.action==='Use shared resource'){const i=sourceOptions(sourceById(n.resourceSourceId),m).find(i=>i.id===n.resourceId);d.items[i.id]=structuredClone(i);n.itemId=i.id;}}return d;};
const sourceOldGraph=drawGraph;
drawGraph=function(){sourceOldGraph();for(const n of sop().nodes){if(n.type==='condition'){const q=sop().nodes.find(q=>q.id===n.source);if(q?.catalogueSourceId){const meta=document.querySelector('[data-node="'+n.id+'"] .nmeta'),choice=nodeCatalogue(q).find(i=>i.id===n.value);if(meta)meta.textContent=n.op+' '+(choice?.name||'Unavailable record');}}if(n.action==='Use shared resource'){const el=document.querySelector('[data-node="'+n.id+'"] .nmeta'),i=sourceOptions(sourceById(n.resourceSourceId),current).find(i=>i.id===n.resourceId);if(el)el.textContent=i?.name||'Choose shared resource';}}};
const sourceOldItemModal=itemModal;
itemModal=function(id){sourceOldItemModal(id);const i=itemById(id);if(!i)return;const inherited=ensureSources().filter(s=>s.kind==='items'&&s.owner===i.module&&s.categoryId===i.categoryId&&s.shares.length);if(inherited.length)$('#itemshares').insertAdjacentHTML('beforebegin',`<div class="notice">Additional access through shared sources: ${inherited.map(s=>esc(s.name)+' → '+s.shares.map(esc).join(', ')).join('; ')}. Change this in Common → Data sources.</div>`);};

function commitSource(next){if(!canEdit()||!next)return;const old=sourceById(next.id);if(old)state.dataSources[state.dataSources.indexOf(old)]=next;else state.dataSources.push(next);window.pendingSource=null;record('Saved source '+next.name);closeModal();render();toast('Source saved. Published SOP snapshots are unchanged.');}
